#include "Monstey_PlacementReference.hpp"
#include <bit>
#include <limits>
namespace Monstey_PlacementReview {
Monstey_Fault::Monstey_Fault(Monstey_FaultKind k,Monstey_U64 p,Monstey_U64 a,unsigned w,bool wr,Monstey_U32 c,Monstey_U32 d):std::runtime_error("independent placement effect fault"),kind(k),pc(p),address(a),width(w),writing(wr),comparand(c),desired(d){}
Monstey_U64 Monstey_Image::Read(Monstey_U64 a,unsigned n,Monstey_U64 pc)const{if(n==0||n>8||a<base||a>std::numeric_limits<Monstey_U64>::max()-(n-1)||a-base>bytes.size()||n>bytes.size()-static_cast<std::size_t>(a-base))throw Monstey_Fault(Monstey_FaultKind::memory,pc,a,n);Monstey_U64 out=0;for(unsigned i=0;i<n;++i)out|=Monstey_U64(bytes[static_cast<std::size_t>(a-base)+i])<<(8u*i);if(passive)passive->push_back({false,pc,a,out,n});return out;}
void Monstey_Image::Write(Monstey_U64 a,Monstey_U64 v,unsigned n,Monstey_U64 pc)const{if(n==0||n>8||a<base||a>std::numeric_limits<Monstey_U64>::max()-(n-1)||a-base>bytes.size()||n>bytes.size()-static_cast<std::size_t>(a-base))throw Monstey_Fault(Monstey_FaultKind::memory,pc,a,n,true);if(passive)passive->push_back({true,pc,a,v,n});for(unsigned i=0;i<n;++i)bytes[static_cast<std::size_t>(a-base)+i]=static_cast<std::uint8_t>(v>>(8u*i));}
namespace {
Monstey_Raw Monstey_Reset(Monstey_Image m,Monstey_U64 o,Monstey_U64 d,Monstey_U64 site){Monstey_U64 head=0;for(Monstey_U32 i=0;i<32;++i){head=o+(Monstey_U64(i)*2+9)*8;m.Write(head+0x18,head,8,site+0x12);m.Write(head+0x10,head,8,site+0x16);}return {head,d};}
Monstey_TailResult Monstey_Tail(Monstey_Image m,Monstey_U64 o,Monstey_U64 x,Monstey_U64 n,Monstey_U64 cell,Monstey_U64 site,bool first){const auto r=x&7;const Monstey_U64 pad=r==0?0:(Monstey_U64{0}-r)&7;const auto q=x+pad,remaining=n-pad;const Monstey_U64 k=first?0:8;m.Write(o+0x28,q,8,site+0x10+k);m.Write(o+0x10,remaining,8,site+0x17+k);m.Write(q+8,remaining|1,8,site+0x1F+k);m.Write(q+remaining+8,0x48,8,site+0x23+k);const auto global=m.Read(cell,8,site+0x2C+k);m.Write(o+0x30,global,8,site+0x33+k);return {{global,q},remaining};}
}
Monstey_Raw Monstey_RefReset40(Monstey_Image m,Monstey_U64 o,Monstey_U64 d){return Monstey_Reset(m,o,d,0x1411755CC);}
Monstey_Raw Monstey_RefReset80(Monstey_Image m,Monstey_U64 o,Monstey_U64 d){return Monstey_Reset(m,o,d,0x141173A14);}
Monstey_Raw Monstey_RefResetC0(Monstey_Image m,Monstey_U64 o,Monstey_U64 d){return Monstey_Reset(m,o,d,0x141176B24);}
Monstey_TailResult Monstey_RefTail40(Monstey_Image m,Monstey_U64 o,Monstey_U64 x,Monstey_U64 n,Monstey_Cells c){return Monstey_Tail(m,o,x,n,c.g40,0x1404875C0,true);}
Monstey_TailResult Monstey_RefTail80(Monstey_Image m,Monstey_U64 o,Monstey_U64 x,Monstey_U64 n,Monstey_Cells c){return Monstey_Tail(m,o,x,n,c.g80,0x141173B60,false);}
Monstey_TailResult Monstey_RefTailC0(Monstey_Image m,Monstey_U64 o,Monstey_U64 x,Monstey_U64 n,Monstey_Cells c){return Monstey_Tail(m,o,x,n,c.gc0,0x141176C70,false);}
Monstey_CasResult Monstey_RefWord(Monstey_Image m,Monstey_U64 target,Monstey_U64 expected,Monstey_U64 desired,Monstey_U64 e,const Monstey_Services&s,Monstey_Cells c){Monstey_U32 policy=5;const auto first=static_cast<Monstey_U32>(m.Read(e+0x28,4,0x14059D5C0));if(first<=5){const auto second=static_cast<Monstey_U32>(m.Read(e+0x28,4,0x14059D5C6));const auto index=static_cast<Monstey_U64>(static_cast<std::int64_t>(std::bit_cast<std::int32_t>(second)));policy=static_cast<Monstey_U32>(m.Read(c.table+index*4,4,0x14059D5D2));}const auto signed_policy=std::bit_cast<std::int32_t>(policy);if(signed_policy<0||signed_policy>5)return {{0,expected},desired,target};const Monstey_U64 site=policy<=3?0x14059D608:0x14059D5F3;const auto comparand=static_cast<Monstey_U32>(m.Read(expected,4,policy<=3?0x14059D606:0x14059D5F1));const auto low=static_cast<Monstey_U32>(desired);if(!s.cas)throw Monstey_Fault(Monstey_FaultKind::missing_cas,site,target,4,false,comparand,low);const auto old=s.cas(m,{site,target,comparand,low});const bool success=old==comparand;if(!success)m.Write(expected,old,4,0x14059D5FD);return {{success?1u:0u,expected},desired,target};}
Monstey_CasResult Monstey_RefState(Monstey_Image m,Monstey_U64 target,Monstey_U64 expected,Monstey_U64 f,const Monstey_Services&s,Monstey_Cells c){m.Write(f+0x20,5,4,0x141173584);auto out=Monstey_RefWord(m,target,expected,0xFFFFFFFFu,f-8,s,c);out.raw.a=static_cast<Monstey_U32>(out.raw.a)!=0?1u:0u;return out;}
}
